// 45 - On-Demand Analysis (self-contained: mock data + normalize + baseline + health, for quick webhook response)
const body = $json.body || $json;
const businessId = body.business_id || 'demo-business';
const analysisType = body.analysis_type || 'full';

// Re-use the same mock generation logic inline for a fast synchronous response.
function genDay(i, scenario) {
  const base = { revenue: 11000, orders: 140, conversion_rate: 3.2, response_time_minutes: 18,
    overdue_invoices: 4, negative_reviews: 1, failed_tasks: 1, workload_score: 55, cost_per_lead: 13.3 };
  const noise = (v, pct) => Math.round(v * (1 + (Math.sin(i*1.7)+Math.random()-0.5) * pct));
  const day = {};
  Object.keys(base).forEach(k => day[k] = noise(base[k], 0.04));
  return day;
}
const history = []; for (let i=0;i<30;i++) history.push(genDay(i));
const current = history[history.length-1];
function avg(arr,key){ return arr.reduce((s,x)=>s+x[key],0)/arr.length; }
const avg7 = {}; Object.keys(current).forEach(k => avg7[k] = avg(history.slice(-7), k));
const score = Math.max(0, Math.min(100, Math.round(100 - Math.max(0,(avg7.revenue-current.revenue)/avg7.revenue*100)*1.5)));
let status = score>=90?'HEALTHY':score>=75?'STABLE':score>=60?'AT_RISK':score>=40?'CRITICAL':'SEVERE';

return [{ json: {
  business_id: businessId, analysis_type: analysisType,
  business_health_score: score, status,
  active_incidents: [],
  top_risks: [],
  recommended_actions: ['Run the full scheduled monitoring workflow for a complete incident analysis.']
} }];

// 42 - Build Daily Business Summary
const items = $input.all().map(i => i.json);
// naive split: assume first set are incidents, second health scores (merge combine may interleave; adjust in real use)
const incidents = items.filter(i => i.incident_id);
const healthLogs = items.filter(i => i.business_health_score);

const latestHealth = healthLogs.sort((a,b)=> new Date(b.timestamp)-new Date(a.timestamp))[0] || { business_health_score: 'N/A', status: 'N/A' };
const active = incidents.filter(i => i.resolution_status === 'ACTIVE');
const resolved = incidents.filter(i => i.resolution_status === 'RESOLVED');
const topRisks = active.sort((a,b)=> (b.risk_score||0) - (a.risk_score||0)).slice(0,5);

const lines = [];
lines.push(`BUSINESS HEALTH: ${latestHealth.business_health_score}/100 — ${latestHealth.status}`);
lines.push('');
lines.push('Top Risks:');
topRisks.forEach((r,i)=> lines.push(`${i+1}. ${r.description} — ${r.severity}`));
lines.push('');
lines.push(`Resolved incidents (recent): ${resolved.length}`);
lines.push(`Unresolved / active incidents: ${active.length}`);

return [{ json: { summary_text: lines.join('\n'), active_count: active.length, resolved_count: resolved.length, health: latestHealth } }];

