const d = $json;
const before = d.before_value;
const after = d.after_value;
const target = d.baseline_target;

// improvement relative to the gap that existed between "before" and the healthy baseline
const gapBefore = Math.abs(before - target);
const gapAfter = Math.abs(after - target);
const improvementPct = gapBefore === 0 ? 100 : +(((gapBefore - gapAfter) / gapBefore) * 100).toFixed(1);

let outcome = 'NOT_RESOLVED';
if (improvementPct >= 70) outcome = 'RESOLVED';
else if (improvementPct >= 30) outcome = 'PARTIALLY_RESOLVED';
else if (improvementPct < 0) outcome = 'WORSENED';

const confidence = Math.min(0.95, 0.5 + Math.abs(improvementPct) / 200);

return [{ json: { ...d, verification: { resolved: outcome === 'RESOLVED', outcome, improvement_percentage: improvementPct, confidence } } }];

// 30 - Recheck Metrics (Simulated)
// More robust version that works even if baseline/metric structure is incomplete

const input = $json;

// Try to get the full context
const d = input.incident_context || input;

const metric = d.metric || d.plan?.metric || 'revenue';

// Try to get the "before" value safely
let before = 100; // default fallback
let target = 110; // default fallback

try {
  if (d.baseline && d.baseline[metric]) {
    before = d.baseline[metric].current ?? d.baseline[metric].rolling_7d_avg ?? 100;
    target = d.baseline[metric].rolling_7d_avg ?? before * 1.1;
  } else if (d.current && d.current[metric]) {
    before = d.current[metric];
    target = before * 1.1;
  }
} catch (e) {
  // keep the default values
}

// Simulate 60-90% improvement toward the target
const improvementFactor = 0.6 + Math.random() * 0.3;
const after = before + (target - before) * improvementFactor;

return [{
  json: {
    ...input,
    metric: metric,
    before_value: before,
    after_value: +after.toFixed(2),
    baseline_target: target,
    incident_context: d          // keep the context for later nodes
  }
}];

// Build the action-execution record for the Actions table.
