try { plan = typeof $json.output === 'string' ? JSON.parse($json.output) : $json.output; }
catch (e) { plan = null; }
const prev = $('17 - Risk Scoring Engine').item.json;

if (!plan || !plan.execution_method) {
  plan = {
    incident_id: prev.incident_id, immediate_action: 'Escalate to human for manual review',
    short_term_action: 'N/A', long_term_prevention: 'N/A', owner: 'Operations Manager',
    expected_outcome: 'N/A', execution_method: 'APPROVAL_REQUIRED', execution_channel: 'EMAIL'
  };
}

const NEVER_AUTOMATE_KEYWORDS = [
  'transfer funds', 'wire transfer', 'delete', 'terminate employee', 'fire ',
  'contract', 'legal agreement', 'bank account', 'payroll change'
];
const text = `${plan.immediate_action} ${plan.short_term_action}`.toLowerCase();
const hitsDangerKeyword = NEVER_AUTOMATE_KEYWORDS.some(k => text.includes(k));

let finalCategory = plan.execution_method;
if (hitsDangerKeyword) finalCategory = 'NEVER_AUTOMATE';
if (!['SAFE_AUTOMATION','APPROVAL_REQUIRED','NEVER_AUTOMATE'].includes(finalCategory)) {
  finalCategory = 'APPROVAL_REQUIRED'; // safe default
}

plan.incident_id = prev.incident_id;
plan.final_execution_category = finalCategory;

return [{ json: { ...prev, plan, state: 'PLANNING' } }];

