// 10 - Dedupe Check & Split: for each detected anomaly, check whether an
// ACTIVE incident already exists for the same business+metric+category.
// This node reads the full anomalies array directly from node 05 (instead
// of relying on a prior Split node + per-item pairing), and outputs ONE
// item per anomaly - so it does both the "dedupe check" AND the "split"
// in a single, unambiguous step.
const anomalies = $('05 - Detect Anomalies').first().json.anomalies;
const activeIncidents = $input.all().map(i => i.json).filter(inc => inc.incident_id);

return anomalies.map(anomaly => {
  const existing = activeIncidents.find(inc =>
    inc.business_id === anomaly.business_id &&
    inc.metric === anomaly.metric &&
    inc.category === anomaly.category
  );
  return { json: { anomaly, isDuplicate: !!existing, existingIncidentId: existing ? existing.incident_id : null } };
});

// 06 - Business Health Score (weighted 0-100)
const d = $json;
const b = d.baseline;

function clampScore(deltaPct, sensitivity) {
  // deltaPct negative = bad for "higher is better" metrics
  let score = 100 + (deltaPct * sensitivity);
  return Math.max(0, Math.min(100, score));
}

const salesHealth = clampScore(b.revenue.change_vs_7d_avg_pct, 1.5);
const customerHealth = 100 - Math.max(0, b.response_time_minutes.change_vs_7d_avg_pct) * 1.2
                              - Math.max(0, b.complaints.change_vs_7d_avg_pct) * 0.8;
const financeHealth = 100 - Math.max(0, b.overdue_invoices.change_vs_7d_avg_pct) * 1.0;
const opsHealth = 100 - Math.max(0, b.failed_tasks.change_vs_7d_avg_pct) * 1.0
                       - Math.max(0, b.pending_tasks ? 0 : 0);
const marketingHealth = 100 - Math.max(0, b.cost_per_lead.change_vs_7d_avg_pct) * 0.8;
const workforceHealth = 100 - Math.max(0, b.workload_score.change_vs_7d_avg_pct) * 1.0;

const dims = {
  sales: Math.max(0, Math.min(100, salesHealth)),
  customer: Math.max(0, Math.min(100, customerHealth)),
  finance: Math.max(0, Math.min(100, financeHealth)),
  operations: Math.max(0, Math.min(100, opsHealth)),
  marketing: Math.max(0, Math.min(100, marketingHealth)),
  workforce: Math.max(0, Math.min(100, workforceHealth))
};

const weights = { sales:0.25, customer:0.20, finance:0.20, operations:0.15, marketing:0.10, workforce:0.10 };
let score = 0;
Object.keys(weights).forEach(k => score += dims[k]*weights[k]);
score = Math.round(score);

let status = 'HEALTHY';
if (score < 40) status = 'SEVERE';
else if (score < 60) status = 'CRITICAL';
else if (score < 75) status = 'AT_RISK';
else if (score < 90) status = 'STABLE';

const reasons = [];
if (b.revenue.change_vs_7d_avg_pct < -5) reasons.push(`Revenue down ${Math.abs(b.revenue.change_vs_7d_avg_pct)}%`);
if (b.response_time_minutes.change_vs_7d_avg_pct > 5) reasons.push(`Response time up ${b.response_time_minutes.change_vs_7d_avg_pct}%`);
if (b.overdue_invoices.change_vs_7d_avg_pct > 5) reasons.push(`Overdue invoices up ${b.overdue_invoices.change_vs_7d_avg_pct}%`);

return [{ json: {
  business_id: d.business_id, timestamp: d.timestamp,
  business_health_score: score, status, dimensions: dims, main_reasons: reasons
} }];

// 05 - Detect Anomalies (deterministic thresholds, NOT an LLM call)
// NOTE: we compare against the 30-day baseline, not the 7-day rolling average.
// A short-term trend (e.g. a 9-day decline) partly sits INSIDE the 7-day window
// itself, which dilutes the signal. The 30-day window has far more "normal" days
// in it, so a genuine anomaly shows up clearly against it.
const d = $json;
const b = d.baseline;
const anomalies = [];

function push(category, metric, changePct, severity, description) {
  anomalies.push({
    anomaly_id: `${d.business_id}-${metric}-${Date.now()}`,
    category, metric, change_percentage: changePct, severity,
    description, business_id: d.business_id, timestamp: d.timestamp
  });
}

// Sales anomaly: revenue drop >= 20% vs 30-day baseline
if (b.revenue.deviation_from_30d_baseline_pct <= -20) {
  push('SALES', 'revenue', b.revenue.deviation_from_30d_baseline_pct, 'HIGH',
    `Revenue dropped ${Math.abs(b.revenue.deviation_from_30d_baseline_pct)}% vs 30-day baseline`);
}
if (b.conversion_rate.deviation_from_30d_baseline_pct <= -20) {
  push('SALES', 'conversion_rate', b.conversion_rate.deviation_from_30d_baseline_pct, 'MEDIUM',
    `Conversion rate dropped ${Math.abs(b.conversion_rate.deviation_from_30d_baseline_pct)}% vs 30-day baseline`);
}

// Customer support anomaly: response time up >= 40%
if (b.response_time_minutes.deviation_from_30d_baseline_pct >= 40) {
  push('CUSTOMER_SUPPORT', 'response_time_minutes', b.response_time_minutes.deviation_from_30d_baseline_pct, 'CRITICAL',
    `Customer response time increased ${b.response_time_minutes.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}
if (b.complaints.deviation_from_30d_baseline_pct >= 30) {
  push('CUSTOMER_SUPPORT', 'complaints', b.complaints.deviation_from_30d_baseline_pct, 'MEDIUM',
    `Complaints increased ${b.complaints.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}

// Finance anomaly: overdue invoices up >= 25%
if (b.overdue_invoices.deviation_from_30d_baseline_pct >= 25) {
  push('FINANCE', 'overdue_invoices', b.overdue_invoices.deviation_from_30d_baseline_pct, 'HIGH',
    `Overdue invoices increased ${b.overdue_invoices.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}

// Reputation anomaly: negative reviews up >= 30%
if (b.negative_reviews.deviation_from_30d_baseline_pct >= 30) {
  push('REPUTATION', 'negative_reviews', b.negative_reviews.deviation_from_30d_baseline_pct, 'MEDIUM',
    `Negative reviews increased ${b.negative_reviews.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}

// Operations anomaly: failed tasks up sharply
if (b.failed_tasks.deviation_from_30d_baseline_pct >= 50) {
  push('OPERATIONS', 'failed_tasks', b.failed_tasks.deviation_from_30d_baseline_pct, 'MEDIUM',
    `Failed tasks increased ${b.failed_tasks.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}

// Workforce anomaly
if (b.workload_score.deviation_from_30d_baseline_pct >= 35) {
  push('WORKFORCE', 'workload_score', b.workload_score.deviation_from_30d_baseline_pct, 'LOW',
    `Employee workload score increased ${b.workload_score.deviation_from_30d_baseline_pct}% vs 30-day baseline`);
}

return [{ json: { ...d, anomalies, anomaly_count: anomalies.length } }];

// 04 - Calculate Historical Baseline (rolling averages, deltas, trend)
const d = $json;
const hist = d.history;
const c = d.current;
const prevDay = d.previousDay;

function avg(arr, key) { return arr.reduce((s,x)=>s+x[key],0) / arr.length; }
function pctChange(cur, base) { return base === 0 ? 0 : +(((cur-base)/base)*100).toFixed(2); }

const last7 = hist.slice(-7);
const last30 = hist.slice(-30);
const prevWeek = hist.slice(-14,-7);

const metrics = ['revenue','orders','conversion_rate','response_time_minutes','complaints',
  'negative_reviews','overdue_invoices','overdue_amount','pending_tasks','failed_tasks',
  'workload_score','cost_per_lead'];

const baseline = {};
metrics.forEach(m => {
  const cur = c[m];
  const avg7 = avg(last7, m);
  const avg30 = avg(last30, m);
  const avgPrevWeek = avg(prevWeek, m);
  baseline[m] = {
    current: cur,
    previous_day: prevDay[m],
    rolling_7d_avg: +avg7.toFixed(2),
    rolling_30d_avg: +avg30.toFixed(2),
    previous_week_avg: +avgPrevWeek.toFixed(2),
    change_vs_prev_day_pct: pctChange(cur, prevDay[m]),
    change_vs_7d_avg_pct: pctChange(cur, avg7),
    change_vs_prev_week_pct: pctChange(avg7, avgPrevWeek),
    deviation_from_30d_baseline_pct: pctChange(cur, avg30),
    trend: cur > avg7 ? 'UP' : (cur < avg7 ? 'DOWN' : 'FLAT')
  };
});

return [{ json: { ...d, baseline } }];

// 03 - Normalize Metrics into the internal business schema
const d = $json;
const c = d.current;

const normalized = {
  timestamp: d.timestamp,
  business_id: d.business_id,
  scenario: d.scenario,
  sales: {
    revenue: c.revenue, orders: c.orders, conversion_rate: c.conversion_rate,
    new_leads: c.new_leads, qualified_leads: c.qualified_leads
  },
  customers: {
    complaints: c.complaints, negative_reviews: c.negative_reviews,
    response_time_minutes: c.response_time_minutes, churn_signals: c.churn_signals
  },
  finance: { overdue_invoices: c.overdue_invoices, overdue_amount: c.overdue_amount },
  operations: { pending_tasks: c.pending_tasks, failed_tasks: c.failed_tasks, inventory_risk: c.inventory_risk },
  employees: { workload_score: c.workload_score, overdue_tasks: c.overdue_tasks_emp },
  marketing: { ad_spend: c.ad_spend, leads: c.mkt_leads, cost_per_lead: c.cost_per_lead }
};

return [{ json: { ...d, normalized } }];

// 02 - Generate Mock Business Data
// Produces: current metrics snapshot + 30 days of historical metrics for one business.
// Replace this node with real Google Sheets / CRM / HubSpot / Shopify / Ads pulls later.

const businessId = ($json.business_id) || 'demo-business';
const scenario = ($json.scenario) || 'sales_decline'; // sales_decline | support_delay | multi_risk | normal

function genDay(i, scenario) {
  const base = {
    revenue: 11000, orders: 140, conversion_rate: 3.2, new_leads: 60, qualified_leads: 22,
    complaints: 3, negative_reviews: 1, response_time_minutes: 18, churn_signals: 2,
    overdue_invoices: 4, overdue_amount: 2200,
    pending_tasks: 12, failed_tasks: 1, inventory_risk: 5,
    workload_score: 55, overdue_tasks_emp: 3,
    ad_spend: 400, mkt_leads: 30, cost_per_lead: 13.3
  };
  const noise = (v, pct) => Math.round(v * (1 + (Math.sin(i*1.7)+Math.random()-0.5) * pct));
  const day = { day_index: i };
  Object.keys(base).forEach(k => day[k] = noise(base[k], 0.04));

  // Inject the last ~9 days with a degrading trend depending on scenario
  const daysFromEnd = 29 - i;
  if (scenario === 'sales_decline' && daysFromEnd <= 9) {
    const factor = 1 - (0.03 * (9 - daysFromEnd));
    day.revenue = Math.round(day.revenue * factor);
    day.orders = Math.round(day.orders * factor);
    day.conversion_rate = +(day.conversion_rate * factor).toFixed(2);
  }
  if (scenario === 'support_delay' && daysFromEnd <= 9) {
    const factor = 1 + (0.06 * (9 - daysFromEnd));
    day.response_time_minutes = Math.round(day.response_time_minutes * factor);
    day.complaints = Math.round(day.complaints * factor);
  }
  if (scenario === 'multi_risk' && daysFromEnd <= 9) {
    const factor = 1 - (0.025 * (9 - daysFromEnd));
    const factorUp = 1 + (0.05 * (9 - daysFromEnd));
    day.revenue = Math.round(day.revenue * factor);
    day.response_time_minutes = Math.round(day.response_time_minutes * factorUp);
    day.overdue_invoices = Math.round(day.overdue_invoices * factorUp);
    day.negative_reviews = Math.round(day.negative_reviews * factorUp);
  }
  return day;
}

const history = [];
for (let i = 0; i < 30; i++) history.push(genDay(i, scenario));
const current = history[history.length - 1];
const previousDay = history[history.length - 2];

return [{
  json: {
    business_id: businessId,
    scenario,
    timestamp: new Date().toISOString(),
    current,
    previousDay,
    history
  }
}];
